/**
 * RFC 9562 UUIDv7: a 48-bit millisecond timestamp, a 12-bit counter, then
 * random bits.
 *
 * Time-ordered ids keep B-tree inserts at the right edge of the index (no
 * random page splits, unlike v4) and make "ORDER BY id DESC" mean "newest
 * first". The 12-bit field is a counter (RFC 9562 §6.2, method 1), so ids
 * generated by one process are strictly increasing even within a millisecond.
 *
 * Generated in the app so it works on any Postgres version.
 */

const MAX_COUNTER = 0xfff;

let lastTimestamp = -1;
let counter = 0;

export function uuidv7(now: number = Date.now()): string {
  let timestamp = now;
  if (timestamp > lastTimestamp) {
    // New millisecond: random start in the lower half, leaving room to count up.
    counter = crypto.getRandomValues(new Uint16Array(1))[0] & 0x7ff;
  } else {
    // Same (or earlier, if the clock stepped back) millisecond: keep counting.
    timestamp = lastTimestamp;
    counter += 1;
    if (counter > MAX_COUNTER) {
      timestamp += 1;
      counter = 0;
    }
  }
  lastTimestamp = timestamp;

  const bytes = crypto.getRandomValues(new Uint8Array(16));
  const high = Math.floor(timestamp / 0x10000); // top 32 of the 48 timestamp bits
  const low = timestamp % 0x10000; // bottom 16 bits
  bytes[0] = (high >>> 24) & 0xff;
  bytes[1] = (high >>> 16) & 0xff;
  bytes[2] = (high >>> 8) & 0xff;
  bytes[3] = high & 0xff;
  bytes[4] = (low >>> 8) & 0xff;
  bytes[5] = low & 0xff;
  bytes[6] = 0x70 | (counter >>> 8); // version 7 + counter high nibble
  bytes[7] = counter & 0xff;
  bytes[8] = (bytes[8] & 0x3f) | 0x80; // RFC 9562 variant

  const hex = Array.from(bytes, (byte) => byte.toString(16).padStart(2, "0")).join("");
  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`;
}

const UUID_PATTERN = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

export function isUuid(value: string): boolean {
  return UUID_PATTERN.test(value);
}
